//! Read-only import of a vendor PD log database (FR TGE83E, AC .6).
//!
//! The vendor app saves a PD capture as an SQLite file with these tables
//! (layout from the research notes, `notes/protocol/pd.md` §5.1):
//!
//! - `pd_chart(Time real, VBUS real, IBUS real, CC1 real, CC2 real)`: the
//!   status samples (s, V, A, V, V);
//! - `pd_table(Time real, Vbus real, Ibus real, Raw Blob)`: the records, with
//!   `Raw` the record bytes as the meter sends them (relative timestamp);
//! - `pd_table_key(key integer)`.
//!
//! Every database here is generated by the test from that layout; no vendor
//! file is used.
//!
//! API pinned here: `open_powerz_desktop_lib::pd_import::import_vendor_pd_log(path)
//! -> Result<PdCapture, PdImportError>` opens the database read-only and maps
//! its relative times (s) to session time (ms): a record's row carries the
//! `pd_table` row's VBUS and IBUS, and every `pd_chart` row becomes a status
//! sample for the timeline. A file that is not a vendor PD log is an error.

use std::path::{Path, PathBuf};

use open_powerz_desktop_lib::pd_capture::{PdCapture, PdRow};
use open_powerz_desktop_lib::pd_import::import_vendor_pd_log;
use powerz_protocol::decode::pd_packet::{CaptureClock, PdChunk};
use powerz_protocol::session::CapturedRecord;
use rusqlite::{Connection, params};

/// A fresh scratch directory for one test.
fn scratch(name: &str) -> PathBuf {
    let dir = PathBuf::from(env!("CARGO_TARGET_TMPDIR"))
        .join("pd-vendor-import")
        .join(name);
    let _ = std::fs::remove_dir_all(&dir);
    std::fs::create_dir_all(&dir).expect("scratch dir");
    dir
}

/// A PD message record (b0 bit 7) at relative time `ts` ms.
fn msg(meter: bool, ts: u32, header: u16, body: &[u8]) -> Vec<u8> {
    let len = 8 + body.len();
    let mut r = vec![0x80 | if meter { 0x40 } else { 0 } | (len as u8 - 1)];
    r.extend(ts.to_le_bytes());
    r.push(0x00);
    r.extend(header.to_le_bytes());
    r.extend(body);
    r
}

/// An event record with event byte `code`.
fn event(meter: bool, ts: u32, code: u8) -> Vec<u8> {
    let mut r = vec![0x05 | if meter { 0x40 } else { 0 }];
    r.extend(ts.to_le_bytes());
    r.push(code);
    r
}

const SRC_CAPS: [u8; 8] = [0x2C, 0x91, 0x81, 0x09, 0x2C, 0xD1, 0x02, 0x00];

/// `pd_table` rows: (Time s, Vbus V, Ibus A, Raw).
fn table_rows() -> Vec<(f64, f64, f64, Vec<u8>)> {
    vec![
        (0.0, 5.01, 0.0, event(true, 0, 0x11)),
        (0.04, 5.012, 0.02, msg(false, 40, 0x21A1, &SRC_CAPS)),
        (
            0.042,
            5.012,
            0.021,
            msg(true, 42, 0x1082, &[0x2C, 0xB1, 0x44, 0x13]),
        ),
        (0.05, 5.013, 0.022, msg(false, 50, 0x03A3, &[])),
        (0.2, 9.004, 0.5, msg(false, 200, 0x05A6, &[])),
        (1.25, 0.0, 0.0, event(true, 1_250, 0x04)),
    ]
}

/// `pd_chart` rows: (Time s, VBUS V, IBUS A, CC1 V, CC2 V).
fn chart_rows() -> Vec<(f64, f64, f64, f64, f64)> {
    vec![
        (0.0, 5.01, 0.0, 1.62, 0.0),
        (0.1, 5.012, 0.021, 1.62, 0.0),
        (0.3, 9.004, 0.5, 1.61, 0.0),
        (1.3, 0.0, 0.0, 0.0, 0.0),
    ]
}

/// Write a vendor-layout PD log database at `path`.
fn vendor_db(path: &Path) {
    let db = Connection::open(path).expect("create test database");
    db.execute_batch(
        "create table if not exists pd_chart(Time real, VBUS real, IBUS real, CC1 real, CC2 real);
         create table if not exists pd_table(Time real, Vbus real, Ibus real, Raw Blob);
         create table if not exists pd_table_key(key integer);",
    )
    .expect("vendor tables");
    for (t, v, i, cc1, cc2) in chart_rows() {
        db.execute(
            "insert into pd_chart(Time,VBUS,IBUS,CC1,CC2)values(?,?,?,?,?)",
            params![t, v, i, cc1, cc2],
        )
        .expect("chart row");
    }
    for (k, (t, v, i, raw)) in table_rows().into_iter().enumerate() {
        db.execute(
            "insert into pd_table(Time,Vbus,Ibus,raw)values(?,?,?,?)",
            params![t, v, i, raw],
        )
        .expect("table row");
        db.execute("insert into pd_table_key(key)values(?)", params![k as i64])
            .expect("key row");
    }
    db.close().expect("database closed");
}

fn rows_of(path: &Path) -> Vec<PdRow> {
    let mut pd = import_vendor_pd_log(path).expect("the vendor log imports");
    pd.take_all().unwrap_or_default()
}

#[test]
fn every_pd_table_row_becomes_a_decoded_row_in_order() {
    let dir = scratch("rows");
    let path = dir.join("capture.sqlite");
    vendor_db(&path);
    let names: Vec<String> = rows_of(&path).into_iter().map(|r| r.name).collect();
    assert_eq!(
        names,
        [
            "Attach",
            "Source_Capabilities",
            "Request",
            "Accept",
            "PS_RDY",
            "Hard Reset"
        ]
    );
}

#[test]
fn relative_times_map_to_session_time_and_rows_keep_their_vbus_and_ibus() {
    let dir = scratch("times");
    let path = dir.join("capture.sqlite");
    vendor_db(&path);
    let rows = rows_of(&path);
    let expected = table_rows();
    assert_eq!(rows.len(), expected.len());
    for (row, (t, v, i, _)) in rows.iter().zip(&expected) {
        assert_eq!(row.session_ms, (t * 1000.0).round() as u64, "{row:?}");
        assert!((row.vbus_v - v).abs() < 1e-9, "{row:?}");
        assert!((row.ibus_a - i).abs() < 1e-9, "{row:?}");
    }
    let indices: Vec<u64> = rows.iter().map(|r| r.index).collect();
    assert_eq!(indices, (0..expected.len() as u64).collect::<Vec<_>>());
    assert!(
        rows.windows(2).all(|w| w[0].elapsed_ms <= w[1].elapsed_ms),
        "elapsed time never goes back"
    );
}

#[test]
fn the_decoder_sees_the_records_in_order() {
    let dir = scratch("decoded");
    let path = dir.join("capture.sqlite");
    vendor_db(&path);
    let mut pd = import_vendor_pd_log(&path).expect("imports");
    let rows = pd.take_all().unwrap_or_default();
    let caps = rows
        .iter()
        .find(|r| r.name == "Source_Capabilities")
        .expect("Source_Capabilities row");
    let details = pd
        .details(caps.index)
        .expect("details of an imported record");
    let mut raw = 0x21A1u16.to_le_bytes().to_vec();
    raw.extend(SRC_CAPS);
    assert_eq!(details.raw, raw, "the PD message bytes");
    assert!(!details.fields.is_empty(), "the field tree");
    // Every record decodes as in a live capture of the same records (the
    // Request against the imported capabilities).
    let mut chunk = vec![0u8; 12];
    for (_, _, _, raw) in table_rows() {
        chunk.extend(raw);
    }
    let parsed = PdChunk::parse(&chunk).expect("synthetic records parse");
    let mut clock = CaptureClock::new();
    let live: Vec<CapturedRecord> = parsed
        .records
        .into_iter()
        .map(|record| CapturedRecord {
            elapsed_ms: clock.elapsed_ms(record.time_ms),
            record,
        })
        .collect();
    let mut reference = PdCapture::new();
    reference.push(&live, None);
    let summaries = |rows: &[PdRow]| rows.iter().map(|r| r.summary.clone()).collect::<Vec<_>>();
    assert_eq!(
        summaries(&rows),
        summaries(&reference.take_all().unwrap_or_default())
    );
}

#[test]
fn every_pd_chart_row_becomes_a_status_sample_for_the_timeline() {
    let dir = scratch("chart");
    let path = dir.join("capture.sqlite");
    vendor_db(&path);
    let mut pd = import_vendor_pd_log(&path).expect("imports");
    let samples = pd.take_all_status().unwrap_or_default();
    let expected = chart_rows();
    assert_eq!(samples.len(), expected.len());
    for (s, (t, v, i, cc1, cc2)) in samples.iter().zip(&expected) {
        assert_eq!(s.session_ms, (t * 1000.0).round() as u64, "{s:?}");
        assert!((s.vbus_v - v).abs() < 1e-9, "{s:?}");
        assert!((s.ibus_a - i).abs() < 1e-9, "{s:?}");
        assert!((s.cc1_v - cc1).abs() < 1e-9, "{s:?}");
        assert!((s.cc2_v - cc2).abs() < 1e-9, "{s:?}");
    }
}

#[test]
fn the_import_leaves_the_database_untouched() {
    let dir = scratch("read-only");
    let path = dir.join("capture.sqlite");
    vendor_db(&path);
    let before = std::fs::read(&path).expect("db bytes");
    let listing = |d: &Path| -> Vec<String> {
        let mut names: Vec<String> = std::fs::read_dir(d)
            .expect("list scratch dir")
            .map(|e| {
                e.expect("dir entry")
                    .file_name()
                    .to_string_lossy()
                    .into_owned()
            })
            .collect();
        names.sort();
        names
    };
    let files_before = listing(&dir);

    let rows = rows_of(&path);
    assert_eq!(rows.len(), table_rows().len());

    assert_eq!(
        std::fs::read(&path).expect("db bytes"),
        before,
        "same bytes"
    );
    assert_eq!(listing(&dir), files_before, "no journal, WAL or other file");
}

#[test]
fn a_write_protected_database_still_imports() {
    let dir = scratch("protected");
    let path = dir.join("capture.sqlite");
    vendor_db(&path);
    let mut perms = std::fs::metadata(&path).expect("metadata").permissions();
    perms.set_readonly(true);
    std::fs::set_permissions(&path, perms.clone()).expect("make read-only");

    let result = import_vendor_pd_log(&path);

    #[allow(clippy::permissions_set_readonly_false)]
    perms.set_readonly(false);
    std::fs::set_permissions(&path, perms).expect("make writable again");
    let mut pd = result.expect("a read-only file imports");
    assert_eq!(pd.take_all().map(|r| r.len()), Some(table_rows().len()));
}

#[test]
fn a_database_without_the_pd_table_is_refused() {
    let dir = scratch("not-pd");
    let path = dir.join("other.sqlite");
    let db = Connection::open(&path).expect("create");
    db.execute_batch("create table ufcs_table(Time real, Vbus real, Ibus real, Raw Blob);")
        .expect("table");
    db.close().expect("closed");
    assert!(import_vendor_pd_log(&path).is_err());
}

#[test]
fn a_file_that_is_not_sqlite_is_refused() {
    let dir = scratch("not-sqlite");
    let path = dir.join("capture.sqlite");
    std::fs::write(&path, b"{\"format\":\"pdcap\"}\n").expect("write");
    assert!(import_vendor_pd_log(&path).is_err());
}

#[test]
fn a_missing_file_is_refused_and_not_created() {
    let dir = scratch("missing");
    let path = dir.join("nothing.sqlite");
    assert!(import_vendor_pd_log(&path).is_err());
    assert!(!path.exists(), "the import never creates a database");
}

// ------------------------------------------------ untrusted and live files

#[test]
fn rows_still_in_the_write_ahead_log_import() {
    // The vendor app may hold the log open in WAL mode: committed rows can
    // still sit in the `-wal` file, not yet in the database file.
    let dir = scratch("wal");
    let path = dir.join("capture.sqlite");
    let writer = Connection::open(&path).expect("create");
    writer
        .execute_batch(
            "pragma journal_mode = wal;
             pragma wal_autocheckpoint = 0;
             create table pd_table(Time real, Vbus real, Ibus real, Raw Blob);",
        )
        .expect("WAL database");
    for (t, v, i, raw) in table_rows() {
        writer
            .execute(
                "insert into pd_table(Time,Vbus,Ibus,Raw)values(?,?,?,?)",
                params![t, v, i, raw],
            )
            .expect("row");
    }
    // The writer stays open, so nothing is checkpointed into the file.
    let mut pd = import_vendor_pd_log(&path).expect("imports");
    assert_eq!(pd.take_all().map(|r| r.len()), Some(table_rows().len()));
    drop(writer);
}

#[cfg(unix)]
#[test]
fn a_file_name_with_a_backslash_imports() {
    let dir = scratch("backslash");
    let path = dir.join("pd\\log.sqlite");
    vendor_db(&path);
    assert_eq!(rows_of(&path).len(), table_rows().len());
}

#[test]
fn oversized_raw_blobs_are_skipped_and_counted() {
    use open_powerz_desktop_lib::pd_import::{ImportLimits, import_vendor_pd_log_with};

    let dir = scratch("oversized");
    let path = dir.join("capture.sqlite");
    vendor_db(&path);
    let db = Connection::open(&path).expect("open");
    db.execute(
        "insert into pd_table(Time,Vbus,Ibus,Raw)values(2.0,5.0,0.0,zeroblob(8 * 1024 * 1024))",
        [],
    )
    .expect("an 8 MiB blob");
    db.close().expect("closed");

    let limits = ImportLimits {
        max_raw_bytes: 4096,
        max_rows: 1_000,
    };
    let mut got = import_vendor_pd_log_with(&path, &limits).expect("imports");
    assert_eq!(got.oversized, 1, "the big row is counted");
    assert!(!got.truncated);
    assert_eq!(
        got.capture.take_all().map(|r| r.len()),
        Some(table_rows().len())
    );
}

#[test]
fn the_number_of_rows_imported_is_capped_and_reported() {
    use open_powerz_desktop_lib::pd_import::{ImportLimits, import_vendor_pd_log_with};

    let dir = scratch("capped");
    let path = dir.join("capture.sqlite");
    vendor_db(&path);
    let limits = ImportLimits {
        max_raw_bytes: 4096,
        max_rows: 3,
    };
    let mut got = import_vendor_pd_log_with(&path, &limits).expect("imports");
    assert!(got.truncated, "the cap is reported");
    assert_eq!(got.capture.take_all().map(|r| r.len()), Some(3));
    assert!(
        got.capture.take_all_status().unwrap_or_default().len() <= 3,
        "the status samples are capped too"
    );
}

// ---- AC-4PJRVK.6: rows without a whole record are counted ----

#[test]
fn rows_without_a_whole_record_are_skipped_and_counted() {
    use open_powerz_desktop_lib::pd_import::{ImportLimits, import_vendor_pd_log_with};

    let dir = scratch("skipped");
    let path = dir.join("capture.sqlite");
    vendor_db(&path);
    let db = Connection::open(&path).expect("open");
    for raw in [
        "insert into pd_table(Time,Vbus,Ibus,Raw)values(2.0,5.0,0.0,NULL)",
        "insert into pd_table(Time,Vbus,Ibus,Raw)values(2.1,5.0,0.0,'text, not bytes')",
        "insert into pd_table(Time,Vbus,Ibus,Raw)values(2.2,5.0,0.0,x'FFFF')",
    ] {
        db.execute(raw, []).expect("a row without a record");
    }
    db.close().expect("closed");

    let mut got = import_vendor_pd_log_with(&path, &ImportLimits::DEFAULT).expect("imports");
    assert_eq!(got.skipped, 3, "every row without a record is counted");
    assert_eq!(got.oversized, 0);
    assert_eq!(
        got.capture.take_all().map(|r| r.len()),
        Some(table_rows().len()),
        "the good rows are all imported"
    );
}

#[test]
fn a_clean_log_skips_nothing() {
    use open_powerz_desktop_lib::pd_import::{ImportLimits, import_vendor_pd_log_with};

    let dir = scratch("nothing-skipped");
    let path = dir.join("capture.sqlite");
    vendor_db(&path);
    let got = import_vendor_pd_log_with(&path, &ImportLimits::DEFAULT).expect("imports");
    assert_eq!(got.skipped, 0);
}
